-- EarthScape hosted edition. Run once in a NEW Supabase project's SQL Editor.
-- es_ names are separate from Supabase Auth and the original local database.
begin;
create table if not exists public.es_users(name text primary key,salt text not null,hash text not null,role text not null check(role in ('admin','analyst','viewer')));
create table if not exists public.es_observations(id bigint generated by default as identity primary key,day text not null,station text not null,temperature double precision,rainfall double precision,co2 double precision,source text not null,timestamp text not null,unique(timestamp,station,source));
create table if not exists public.es_alerts(id bigint generated by default as identity primary key,created text not null,station text not null,message text not null,ack integer not null default 0);
create table if not exists public.es_tickets(id bigint generated by default as identity primary key,created text not null,owner text not null,subject text not null,body text not null,status text not null default 'Open');
create table if not exists public.es_settings(key text primary key,value text not null);
create table if not exists public.es_audit(id bigint generated by default as identity primary key,created text not null,actor text not null,action text not null);
create table if not exists public.es_assets(id bigint generated by default as identity primary key,created text not null,name text not null,kind text not null default 'satellite',payload text not null);
create table if not exists public.es_jobs(id bigint generated by default as identity primary key,created text not null,status text not null,output text,error text,input_snapshot jsonb);
create table if not exists public.es_sessions(token_hash text primary key,name text not null references public.es_users(name) on delete cascade,csrf text not null,expires double precision not null);
create table if not exists public.es_login_attempts(key text primary key,window_start double precision not null,attempts integer not null);
create table if not exists public.es_backups(id bigint generated by default as identity primary key,created text not null,name text not null,payload text not null);
create index if not exists es_station_day on public.es_observations(station,day);
insert into public.es_settings values('threshold','40') on conflict do nothing;
-- Every table denies browser access. Only the server-only service_role may access it.
do $$ declare t text; begin
 foreach t in array array['es_users','es_observations','es_alerts','es_tickets','es_settings','es_audit','es_assets','es_jobs','es_sessions','es_login_attempts','es_backups'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from anon, authenticated',t);
  execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;
grant usage,select on all sequences in schema public to service_role;
create or replace function public.es_observations() returns jsonb language sql set search_path=public as $$
 select coalesce(jsonb_agg(t order by t.day,t.id),'[]'::jsonb) from (select * from public.es_observations order by day,id limit 5000) t;
$$;
create or replace function public.es_ingest(p_rows jsonb,p_actor text) returns jsonb language plpgsql set search_path=public as $$
declare r jsonb; n integer:=0; added integer; threshold double precision;
begin
 lock table public.es_observations in share row exclusive mode;
 if jsonb_array_length(p_rows)>1000 or (select count(*) from public.es_observations)+jsonb_array_length(p_rows)>5000 then raise exception 'Portfolio demo is limited to 5000 observations';end if;
 select value::double precision into threshold from public.es_settings where key='threshold';
 for r in select * from jsonb_array_elements(p_rows) loop
  insert into public.es_observations(day,station,temperature,rainfall,co2,source,timestamp)
  values(r->>'day',r->>'station',(r->>'temperature')::double precision,(r->>'rainfall')::double precision,(r->>'co2')::double precision,r->>'source',r->>'timestamp') on conflict do nothing;
  get diagnostics added=row_count;n:=n+added;
  if added>0 and (r->>'temperature')::double precision>threshold then
   insert into public.es_alerts(created,station,message) values(now()::text,r->>'station','Temperature '||(r->>'temperature')||' C exceeds '||threshold||' C');
  end if;
 end loop;
 insert into public.es_audit(created,actor,action) values(now()::text,p_actor,'Ingest: '||n||' accepted');
 return jsonb_build_object('inserted',n,'duplicates',jsonb_array_length(p_rows)-n);
end $$;
create or replace function public.es_login_gate(p_key text) returns boolean language plpgsql set search_path=public as $$
declare n integer; t double precision:=extract(epoch from now());begin
 delete from public.es_login_attempts where window_start<t-600;
 insert into public.es_login_attempts values(p_key,t,1) on conflict(key) do update set
 attempts=case when es_login_attempts.window_start<t-300 then 1 else es_login_attempts.attempts+1 end,
 window_start=case when es_login_attempts.window_start<t-300 then t else es_login_attempts.window_start end returning attempts into n;
 return n<=20;
end $$;
create or replace function public.es_status() returns jsonb language sql set search_path=public as $$
 select jsonb_build_object('uptime_seconds',0,'storage','Supabase PostgreSQL','threshold',(select value::float from public.es_settings where key='threshold'),'database_bytes',pg_database_size(current_database()),'records',(select count(*) from public.es_observations),'metrics',jsonb_build_object('requests',0,'errors',0),'average_response_ms',0);
$$;
create or replace function public.es_process(p_actor text) returns jsonb language plpgsql set search_path=public as $$
declare jid bigint; summary text; groups integer; result jsonb;begin
 lock table public.es_jobs in share row exclusive mode;
 if (select count(*) from public.es_jobs where created::timestamptz>now()-interval '1 hour')>=20 then raise exception 'Hourly processing limit reached';end if;
 select count(*),string_agg(station||'|'||month_key||E'\t'||round(mean::numeric,4)||E'\t'||n,E'\n' order by station,month_key) into groups,summary from
 (select station,left(day,7) as month_key,avg(temperature) mean,count(temperature) n from public.es_observations where temperature is not null group by station,left(day,7)) t;
 result:=jsonb_build_object('engine','PostgreSQL monthly aggregation (no Hadoop)','input_records',(select count(*) from public.es_observations),'groups',groups,'summary',coalesce(summary,''));
 insert into public.es_jobs(created,status,output,input_snapshot) values(now()::text,'Completed',result::text,public.es_observations()) returning id into jid;
 delete from public.es_jobs where id not in(select id from public.es_jobs order by id desc limit 20);
 insert into public.es_audit(created,actor,action) values(now()::text,p_actor,'Monthly aggregation completed');
 return jsonb_build_object('job',jid);
end $$;
create or replace function public.es_ticket(p_owner text,p_subject text,p_body text) returns jsonb language plpgsql set search_path=public as $$
begin
 lock table public.es_tickets in share row exclusive mode;
 if (select count(*) from public.es_tickets)>=500 or (select count(*) from public.es_tickets where owner=p_owner and created::timestamptz>now()-interval '1 hour')>=10 then raise exception 'Demo ticket limit reached';end if;
 insert into public.es_tickets(created,owner,subject,body) values(now()::text,p_owner,p_subject,p_body);return jsonb_build_object('ok',true);
end $$;
create or replace function public.es_save_user(p_name text,p_salt text,p_hash text,p_role text,p_actor text) returns jsonb language plpgsql set search_path=public as $$
begin
 lock table public.es_users in share row exclusive mode;
 if exists(select 1 from public.es_users where name=p_name and role='admin') and p_role<>'admin' and (select count(*) from public.es_users where role='admin')<=1 then raise exception 'Cannot demote last administrator';end if;
 if (select count(*) from public.es_users)>=50 and not exists(select 1 from public.es_users where name=p_name) then raise exception 'Demo user limit reached';end if;
 insert into public.es_users values(p_name,p_salt,p_hash,p_role) on conflict(name) do update set salt=p_salt,hash=p_hash,role=p_role;
 delete from public.es_sessions where name=p_name;
 insert into public.es_audit(created,actor,action) values(now()::text,p_actor,'Account updated: '||p_name);return jsonb_build_object('ok',true);
end $$;
create or replace function public.es_asset(p_name text,p_payload text) returns jsonb language plpgsql set search_path=public as $$
begin
 lock table public.es_assets in share row exclusive mode;
 if coalesce((select sum(length(payload)) from public.es_assets),0)+length(p_payload)>15000000 then raise exception 'Demo archive full (15 MB encrypted data)';end if;
 insert into public.es_assets(created,name,payload) values(now()::text,p_name,p_payload);return jsonb_build_object('ok',true);
end $$;
create or replace function public.es_snapshot() returns jsonb language sql set search_path=public as $$
 select jsonb_build_object('format','EarthScape logical snapshot v1','created',now(),'observations',public.es_observations(),'alerts',(select coalesce(jsonb_agg(t),'[]'::jsonb) from public.es_alerts t),'tickets',(select coalesce(jsonb_agg(t),'[]'::jsonb) from public.es_tickets t),'settings',(select jsonb_agg(t) from public.es_settings t),'assets',(select coalesce(jsonb_agg(t),'[]'::jsonb) from public.es_assets t));
$$;
create or replace function public.es_backup(p_name text,p_payload text) returns jsonb language plpgsql set search_path=public as $$
begin
 lock table public.es_backups in share row exclusive mode;
 if length(p_payload)>25000000 then raise exception 'Snapshot exceeds demo limit';end if;
 insert into public.es_backups(created,name,payload) values(now()::text,p_name,p_payload);
 delete from public.es_backups where id not in(select id from public.es_backups order by id desc limit 3);
 return jsonb_build_object('ok',true);
end $$;
-- Restrict all application RPCs to the server-only role.
do $$ declare f record; begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('es_observations','es_ingest','es_login_gate','es_status','es_process','es_ticket','es_save_user','es_asset','es_snapshot','es_backup') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $$;

